<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php $this->load->view('comman/app_icons'); ?><title><?= htmlspecialchars($SITE_TITLE??'MartPoint',ENT_QUOTES,'UTF-8'); ?> — Abandoned Carts</title><style>body{margin:0;background:#f7f8fc;font:14px system-ui;color:#172033}main{padding:18px 14px 150px;max-width:850px;margin:auto}.store-name{font-size:12px;color:#727b8e}h1{font-size:23px}.cart-card{background:#fff;padding:18px;border:1px solid #e8ebf1;border-radius:14px;margin:16px 0}.btn{display:inline-block;padding:12px 16px;background:#6554c0;color:white;border-radius:9px;text-decoration:none}.muted{color:#727b8e;font-size:12px}a{color:#6554c0}</style></head><body><main><header><div class="store-name"><?= htmlspecialchars($SITE_TITLE??'MartPoint',ENT_QUOTES,'UTF-8'); ?></div><h1>Abandoned Carts</h1></header><a class="btn" href="<?= base_url('communications/channel/automation?section=create&recipe=abandoned_cart&screen=mobile'); ?>">Set up recovery workflow</a><p class="muted">Carts idle for <?= (int)$hours; ?>+ hours. Automatic reminders are managed in Communications → Automation. Your saved carts and recovery history are preserved.</p><?php if(!$enabled): ?><section class="cart-card">Cart tracking is currently off. Ask your Administrator to enable it in Online Store settings.</section><?php endif; ?><?php foreach($carts as $c): ?><section class="cart-card"><h2><?= htmlspecialchars($c->customer_name?:'Customer',ENT_QUOTES,'UTF-8'); ?></h2><p><?= htmlspecialchars($c->customer_email?:($c->customer_phone?:''),ENT_QUOTES,'UTF-8'); ?></p><p>Cart value: ₦<?= number_format((float)$c->subtotal,2); ?></p><p class="muted">Last activity <?= htmlspecialchars($c->last_activity,ENT_QUOTES,'UTF-8'); ?> · <?= (int)$c->reminder_count; ?> / 3 reminders</p><?php if(!empty($can_remind) && !empty($c->customer_phone)):$restore=base_url('store/'.rawurlencode($store_slug).'/cart?cart='.rawurlencode($c->cart_token));$phone=preg_replace('/[^0-9]/','',$c->customer_phone);if(preg_match('/^0[0-9]{10}$/',$phone))$phone='234'.substr($phone,1); ?><button class="btn" style="border:0" data-cart="<?= (int)$c->id; ?>" data-chat="<?= htmlspecialchars('https://wa.me/'.$phone.'?text='.rawurlencode('Hi '.($c->customer_name?:'there').', continue your checkout: '.$restore),ENT_QUOTES,'UTF-8'); ?>">Remind manually on WhatsApp</button><?php endif; ?></section><?php endforeach; ?><?php if(!$carts): ?><section class="cart-card">No abandoned carts right now.</section><?php endif; ?><p id="cart-status" role="status"></p></main><?php $this->load->view('mobile/bottom_nav',array('active'=>'more'));$this->load->view('mobile/chat'); ?><script>document.querySelectorAll('[data-cart]').forEach(function(b){b.onclick=function(){var popup=window.open('about:blank','_blank');if(popup)popup.opener=null;var data=new FormData();data.append('cart_id',b.dataset.cart);data.append('channel','whatsapp');data.append(<?= json_encode($this->security->get_csrf_token_name()); ?>,<?= json_encode($this->security->get_csrf_hash()); ?>);b.disabled=true;fetch(<?= json_encode(base_url('online_store/mark_cart_reminded')); ?>,{method:'POST',credentials:'same-origin',body:data}).then(function(r){return r.json();}).then(function(r){if(r.status!=='success')throw new Error(r.message||'Reminder unavailable.');if(popup)popup.location=b.dataset.chat;else location.href=b.dataset.chat;document.getElementById('cart-status').textContent='Reminder recorded. Complete the message in WhatsApp.';}).catch(function(e){if(popup)popup.close();document.getElementById('cart-status').textContent=e.message||'Please try again.';b.disabled=false;});};});</script></body></html>
